import{_ as o,o as t,c as a,ai as s}from"./chunks/framework.C33Uq6m-.js";const p=JSON.parse('{"title":"Tableau de Bord des Couts","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/cost-dashboard.md","filePath":"fr/guide/cost-dashboard.md"}'),i={name:"fr/guide/cost-dashboard.md"};function l(r,e,n,u,d,c){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="tableau-de-bord-des-couts" tabindex="-1">Tableau de Bord des Couts <a class="header-anchor" href="#tableau-de-bord-des-couts" aria-label="Permalink to &quot;Tableau de Bord des Couts&quot;">​</a></h1><p>Le tableau de bord des couts suit l&#39;utilisation des tokens a travers toutes vos sessions et estime ce que la meme charge de travail couterait sur des APIs cloud commerciales.</p><p><strong>Element de la barre laterale :</strong> Couts <strong>Route :</strong> <code>/costs</code></p><h2 id="pourquoi-suivre-les-couts-localement" tabindex="-1">Pourquoi suivre les couts localement ? <a class="header-anchor" href="#pourquoi-suivre-les-couts-localement" aria-label="Permalink to &quot;Pourquoi suivre les couts localement ?&quot;">​</a></h2><p>Ollama fonctionne sur votre machine sans frais. Mais comprendre le cout cloud equivalent vous aide a :</p><ul><li><strong>Quantifier les economies</strong> -- Voyez combien vous economisez en executant localement</li><li><strong>Planifier la capacite</strong> -- Comprenez quels modeles consomment le plus de tokens</li><li><strong>Comparer l&#39;efficacite</strong> -- Identifiez quels modeles donnent le meilleur resultat par token</li></ul><h2 id="sections-du-tableau-de-bord" tabindex="-1">Sections du tableau de bord <a class="header-anchor" href="#sections-du-tableau-de-bord" aria-label="Permalink to &quot;Sections du tableau de bord&quot;">​</a></h2><h3 id="cartes-de-resume" tabindex="-1">Cartes de resume <a class="header-anchor" href="#cartes-de-resume" aria-label="Permalink to &quot;Cartes de resume&quot;">​</a></h3><p>Quatre cartes en haut affichant :</p><ul><li><strong>Tokens totaux</strong> -- Somme de tous les tokens de prompt + completion</li><li><strong>Sessions</strong> -- Nombre total de sessions de chat enregistrees</li><li><strong>Cout estime</strong> -- Ce que la meme utilisation couterait sur les APIs cloud</li><li><strong>Cout moy./session</strong> -- Cout estime moyen par session</li></ul><h3 id="utilisation-de-tokens-par-modele" tabindex="-1">Utilisation de tokens par modele <a class="header-anchor" href="#utilisation-de-tokens-par-modele" aria-label="Permalink to &quot;Utilisation de tokens par modele&quot;">​</a></h3><p>Un graphique en barres horizontales empilees montrant les tokens de prompt (indigo) et de completion (violet) pour chaque modele utilise. Les modeles sont tries par nombre total de tokens.</p><h3 id="utilisation-quotidienne" tabindex="-1">Utilisation quotidienne <a class="header-anchor" href="#utilisation-quotidienne" aria-label="Permalink to &quot;Utilisation quotidienne&quot;">​</a></h3><p>Un graphique en ligne avec deux axes :</p><ul><li><strong>Axe gauche</strong> -- Tokens totaux par jour (zone remplie)</li><li><strong>Axe droit</strong> -- Cout estime par jour (ligne pointillee)</li></ul><h3 id="tableau-detaille-par-modele" tabindex="-1">Tableau detaille par modele <a class="header-anchor" href="#tableau-detaille-par-modele" aria-label="Permalink to &quot;Tableau detaille par modele&quot;">​</a></h3><p>Un tableau detaille avec les colonnes : Modele, Sessions, Prompt, Completion, Total, Cout est., Source.</p><h2 id="donnees-de-tarification" tabindex="-1">Donnees de tarification <a class="header-anchor" href="#donnees-de-tarification" aria-label="Permalink to &quot;Donnees de tarification&quot;">​</a></h2><p>Les tarifs sont bases sur les prix equivalents des APIs cloud pour les familles de modeles courants. Les modeles non repertories utilisent une estimation generique de $0.10/$0.10 par million de tokens.</p><div class="info custom-block"><p class="custom-block-title">Ce sont des estimations</p><p>Tous les couts affiches representent ce que l&#39;utilisation equivalente couterait sur des APIs cloud. Ollama fonctionne localement sans frais.</p></div>',20)])])}const h=o(i,[["render",l]]);export{p as __pageData,h as default};
